{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h2",
        "intro_text",
        "strategies_h3",
        "strategy_1_card",
        "strategy_2_card",
        "strategy_3_card",
        "strategy_4_card",
        "strategy_5_card",
        "quick_actions_stack"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Email Overload Management in a Professional Setting",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Managing an average of 100 emails per day while ensuring urgent responses within two hours requires a strategic approach. These five strategies focus on reducing volume, improving processing efficiency, and setting clear boundaries to maintain productivity and meet response goals.",
        "variant": "body"
      },
      "children": []
    },
    "strategies_h3": {
      "type": "Text",
      "props": {
        "text": "Five Strategies for Efficient Inbox Control",
        "variant": "h3"
      },
      "children": []
    },
    "strategy_1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "strategy_1_content"
      ]
    },
    "strategy_1_content": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "strategy_1_header",
        "strategy_1_action_label",
        "strategy_1_action_text",
        "strategy_1_benefit_label",
        "strategy_1_benefit_text"
      ]
    },
    "strategy_1_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "strategy_1_icon",
        "strategy_1_title"
      ]
    },
    "strategy_1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000696_01_1_clock.svg"
      },
      "children": []
    },
    "strategy_1_title": {
      "type": "Text",
      "props": {
        "text": "Schedule Dedicated Email Blocks",
        "variant": "h3"
      },
      "children": []
    },
    "strategy_1_action_label": {
      "type": "Text",
      "props": {
        "text": "Action:",
        "variant": "label"
      },
      "children": []
    },
    "strategy_1_action_text": {
      "type": "Text",
      "props": {
        "text": "Instead of constantly checking email, designate 2-3 specific times during the day (e.g., morning, midday, late afternoon) for processing emails.",
        "variant": "body"
      },
      "children": []
    },
    "strategy_1_benefit_label": {
      "type": "Text",
      "props": {
        "text": "Benefit:",
        "variant": "label"
      },
      "children": []
    },
    "strategy_1_benefit_text": {
      "type": "Text",
      "props": {
        "text": "This prevents constant interruptions, allowing for focused work periods. Urgent emails can be triaged quickly during these blocks, adhering to the 2-hour response goal.",
        "variant": "body"
      },
      "children": []
    },
    "strategy_2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "strategy_2_content"
      ]
    },
    "strategy_2_content": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "strategy_2_header",
        "strategy_2_action_label",
        "strategy_2_action_text_stack",
        "strategy_2_benefit_label",
        "strategy_2_benefit_text"
      ]
    },
    "strategy_2_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "strategy_2_icon",
        "strategy_2_title"
      ]
    },
    "strategy_2_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000696_01_2_list-check.svg"
      },
      "children": []
    },
    "strategy_2_title": {
      "type": "Text",
      "props": {
        "text": "Implement the \"4 D's\" for Each Email",
        "variant": "h3"
      },
      "children": []
    },
    "strategy_2_action_label": {
      "type": "Text",
      "props": {
        "text": "Action:",
        "variant": "label"
      },
      "children": []
    },
    "strategy_2_action_text_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "strategy_2_action_intro",
        "strategy_2_action_delete",
        "strategy_2_action_do",
        "strategy_2_action_delegate",
        "strategy_2_action_defer"
      ]
    },
    "strategy_2_action_intro": {
      "type": "Text",
      "props": {
        "text": "For every email, make an immediate decision:",
        "variant": "body"
      },
      "children": []
    },
    "strategy_2_action_delete": {
      "type": "Text",
      "props": {
        "text": "• Delete: If it's junk or irrelevant.",
        "variant": "body"
      },
      "children": []
    },
    "strategy_2_action_do": {
      "type": "Text",
      "props": {
        "text": "• Do: If it takes less than 2 minutes to respond or act on (e.g., a quick urgent reply).",
        "variant": "body"
      },
      "children": []
    },
    "strategy_2_action_delegate": {
      "type": "Text",
      "props": {
        "text": "• Delegate: If someone else is better suited to handle it.",
        "variant": "body"
      },
      "children": []
    },
    "strategy_2_action_defer": {
      "type": "Text",
      "props": {
        "text": "• Defer: If it requires more than 2 minutes and can be handled later (e.g., during a dedicated work block).",
        "variant": "body"
      },
      "children": []
    },
    "strategy_2_benefit_label": {
      "type": "Text",
      "props": {
        "text": "Benefit:",
        "variant": "label"
      },
      "children": []
    },
    "strategy_2_benefit_text": {
      "type": "Text",
      "props": {
        "text": "This systematic approach ensures that every email is processed efficiently, preventing inbox buildup and ensuring urgent items are addressed promptly.",
        "variant": "body"
      },
      "children": []
    },
    "strategy_3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "strategy_3_content"
      ]
    },
    "strategy_3_content": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "strategy_3_header",
        "strategy_3_action_label",
        "strategy_3_action_text",
        "strategy_3_benefit_label",
        "strategy_3_benefit_text"
      ]
    },
    "strategy_3_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "strategy_3_icon",
        "strategy_3_title"
      ]
    },
    "strategy_3_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000696_01_3_funnel.svg"
      },
      "children": []
    },
    "strategy_3_title": {
      "type": "Text",
      "props": {
        "text": "Utilize Email Filters and Rules",
        "variant": "h3"
      },
      "children": []
    },
    "strategy_3_action_label": {
      "type": "Text",
      "props": {
        "text": "Action:",
        "variant": "label"
      },
      "children": []
    },
    "strategy_3_action_text": {
      "type": "Text",
      "props": {
        "text": "Configure email rules to automatically sort non-urgent messages, newsletters, or project-specific communications into designated folders. Prioritize urgent senders or keywords.",
        "variant": "body"
      },
      "children": []
    },
    "strategy_3_benefit_label": {
      "type": "Text",
      "props": {
        "text": "Benefit:",
        "variant": "label"
      },
      "children": []
    },
    "strategy_3_benefit_text": {
      "type": "Text",
      "props": {
        "text": "Keeps your primary inbox clean, reducing visual clutter and allowing you to focus on high-priority emails. Ensures urgent responses are not missed.",
        "variant": "body"
      },
      "children": []
    },
    "strategy_4_card": {
      "type": "Card",
      "props": {},
      "children": [
        "strategy_4_content"
      ]
    },
    "strategy_4_content": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "strategy_4_header",
        "strategy_4_action_label",
        "strategy_4_action_text",
        "strategy_4_benefit_label",
        "strategy_4_benefit_text"
      ]
    },
    "strategy_4_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "strategy_4_icon",
        "strategy_4_title"
      ]
    },
    "strategy_4_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000696_01_4_bell-slash.svg"
      },
      "children": []
    },
    "strategy_4_title": {
      "type": "Text",
      "props": {
        "text": "Unsubscribe and Reduce Volume",
        "variant": "h3"
      },
      "children": []
    },
    "strategy_4_action_label": {
      "type": "Text",
      "props": {
        "text": "Action:",
        "variant": "label"
      },
      "children": []
    },
    "strategy_4_action_text": {
      "type": "Text",
      "props": {
        "text": "Regularly review your subscriptions. Unsubscribe from newsletters, promotional emails, or internal distribution lists that are no longer essential or relevant to your work.",
        "variant": "body"
      },
      "children": []
    },
    "strategy_4_benefit_label": {
      "type": "Text",
      "props": {
        "text": "Benefit:",
        "variant": "label"
      },
      "children": []
    },
    "strategy_4_benefit_text": {
      "type": "Text",
      "props": {
        "text": "Directly decreases the sheer volume of emails entering your inbox daily, freeing up time spent on deleting or archiving irrelevant messages.",
        "variant": "body"
      },
      "children": []
    },
    "strategy_5_card": {
      "type": "Card",
      "props": {},
      "children": [
        "strategy_5_content"
      ]
    },
    "strategy_5_content": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "strategy_5_header",
        "strategy_5_action_label",
        "strategy_5_action_text",
        "strategy_5_benefit_label",
        "strategy_5_benefit_text"
      ]
    },
    "strategy_5_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "strategy_5_icon",
        "strategy_5_title"
      ]
    },
    "strategy_5_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000696_01_5_megaphone.svg"
      },
      "children": []
    },
    "strategy_5_title": {
      "type": "Text",
      "props": {
        "text": "Communicate Response Expectations",
        "variant": "h3"
      },
      "children": []
    },
    "strategy_5_action_label": {
      "type": "Text",
      "props": {
        "text": "Action:",
        "variant": "label"
      },
      "children": []
    },
    "strategy_5_action_text": {
      "type": "Text",
      "props": {
        "text": "Proactively inform colleagues and clients about your typical email response times. Use out-of-office messages for planned absences or when you're in focused work blocks.",
        "variant": "body"
      },
      "children": []
    },
    "strategy_5_benefit_label": {
      "type": "Text",
      "props": {
        "text": "Benefit:",
        "variant": "label"
      },
      "children": []
    },
    "strategy_5_benefit_text": {
      "type": "Text",
      "props": {
        "text": "Manages expectations, reduces the pressure for instant replies, and allows you to adhere to your scheduled email processing times without guilt or constant interruption.",
        "variant": "body"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "paddingVertical": 16
      },
      "children": [
        "quick_actions_title",
        "button_filters",
        "button_subscriptions",
        "button_ooo"
      ]
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "button_filters": {
      "type": "Button",
      "props": {
        "label": "Set Up Email Filters"
      },
      "on": {
        "press": {
          "action": "setState",
          "params": {
            "statePath": "/action/emailFilters",
            "value": "triggered"
          }
        }
      },
      "children": []
    },
    "button_subscriptions": {
      "type": "Button",
      "props": {
        "label": "Review Subscriptions"
      },
      "on": {
        "press": {
          "action": "setState",
          "params": {
            "statePath": "/action/reviewSubscriptions",
            "value": "triggered"
          }
        }
      },
      "children": []
    },
    "button_ooo": {
      "type": "Button",
      "props": {
        "label": "Draft Out-of-Office Message"
      },
      "on": {
        "press": {
          "action": "setState",
          "params": {
            "statePath": "/action/draftOOO",
            "value": "triggered"
          }
        }
      },
      "children": []
    }
  }
}
